UPDATE faqs SET question_sv = 'Hur mycket protein finns i varje måltid?', answer_sv = 'Varje PLÄNTLY-måltid innehåller > 20g komplett växtbaserat protein från ärt- och solrosprotein.' WHERE id = '24381de9-a3a9-4c70-946c-7046804560d3';
UPDATE faqs SET question_sv = 'Är PLÄNTLY 100% veganskt?', answer_sv = 'Alla PLÄNTLY-måltider är 100% växtbaserat protein. Vissa innehåller mjölkpulver — se individuella produktsidor för allergeninformation.' WHERE id = 'bdbc3261-9ac0-4e78-b5c7-4428f36ba699';
UPDATE faqs SET question_sv = 'Hur tillagar jag en PLÄNTLY-måltid?', answer_sv = 'Skaka den, öppna locket, häll kokande vatten till fyllnadslinjen, rör om, stäng locket och vänta 5 minuter. Rör om igen och njut!' WHERE id = 'fd2c85ee-c29a-4e0f-8891-fce176e9c690';
UPDATE faqs SET question_sv = 'Vart skickar ni?', answer_sv = 'Vi skickar för närvarande inom EU och Storbritannien. Kolla vår fraktsida för leveranstider och kostnader till ditt land.' WHERE id = '6d95fc2f-c9e8-4305-8bf9-8acd16f82410';
UPDATE faqs SET question_sv = 'Kan jag prenumerera och spara?', answer_sv = 'Ja! Prenumerera på valfri måltid eller paket och spara 15% på varje beställning. Du kan pausa, hoppa över eller avbryta när som helst.' WHERE id = '8109e942-dccb-4774-be43-28c88a0d8694';
UPDATE faqs SET question_sv = 'Är kopparna återvinningsbara?', answer_sv = 'Ja. Våra koppar är gjorda av återvinningsbart material. Kontrollera dina lokala återvinningsriktlinjer för korrekt hantering.' WHERE id = '833f4f78-5a26-4fc2-bd8f-fe79278eb87f';
UPDATE faqs SET question_sv = 'Vad är hållbarhetstiden?', answer_sv = 'PLÄNTLY-måltider har en hållbarhetstid på 12 månader från produktion. Ingen kylning behövs förrän den öppnats.' WHERE id = 'd9803a9b-2cc9-4ef4-a336-54ef611e83db';
UPDATE faqs SET question_sv = 'Finns det några artificiella ingredienser?', answer_sv = 'Nej. Vi använder bara riktiga, igenkännliga ingredienser. Inga artificiella färgämnen, smaker, sötningsmedel eller konserveringsmedel.' WHERE id = '53f516fe-6f7a-4fc8-8933-9dd1cafbffe8';